// Built for "SMS and push later". Two years on, email is the only channel.
public interface INotificationChannel
{
    string Name { get; }
    Task SendAsync(Notification n, CancellationToken ct);
}

public sealed class ChannelRegistry(IEnumerable<INotificationChannel> all)
{
    public INotificationChannel Get(string name) =>
        all.Single(c => c.Name == name);
}

public sealed class Notifier(ChannelRegistry registry, string channelName)
{
    public Task NotifyAsync(Notification n, CancellationToken ct) =>
        registry.Get(channelName).SendAsync(n, ct);
}

public sealed class EmailChannel(IEmailSender email) : INotificationChannel
{
    public string Name => "email";
    public Task SendAsync(Notification n, CancellationToken ct) =>
        email.SendAsync(n.To, n.Subject, n.Body, ct);
}

// Today's requirement: email a notification. Nothing more.
public sealed class Notifier(IEmailSender email)
{
    public Task NotifyAsync(Notification n, CancellationToken ct) =>
        email.SendAsync(n.To, n.Subject, n.Body, ct);
}
